export type SeatWind = 'east' | 'south' | 'west' | 'north'
export type TileOrientation = 'vertical' | 'horizontal' | 'doublehorizontal' | 'backend'
export type TenpaiStatus = 'tenpai' | 'riichi'
export type TileStatus = 'yaku' | 'noyaku'
export type MeldType = 'chi' | 'pon' | 'minkan' | 'kakan' | 'ankan'
export type SourcePlayer = 'kamicha' | 'toimen' | 'shimocha'

export interface Meld {
  id: string
  seq: string // mahgen 序列字符串，如 "_1m2m3m", "0z5p5p0z" 等
}

export interface TenpaiTile {
  code: string
  status: TileStatus
  count?: number
}

export interface PlayerTenpai {
  status: TenpaiStatus
  isFuriten: boolean
  tiles: TenpaiTile[]
}

export interface TenpaiOption {
  label: string
  ready: boolean
  tiles?: string[]
}

export interface PlayerBoard {
  id: string
  badgeText: string
  badgeColor: string
  playerName: string
  teamName: string
  teamLogoUrl: string
  tagline: string
  score: number
  ptPoint: string
  wind: SeatWind
  highlight: boolean
  melds: Meld[]
  tenpai: PlayerTenpai | null
}

export interface MatchState {
  isKili: boolean
  sessionLabel: string
  currentRound: string
  matchNumber: number
  fieldSupply: string
  treasureTile: string[]
  matchName: string
  matchLogoUrl: string
  subtitle: string
  subtitle2: string 
  subtitle3: string
  honba: number
  riichiSticks: number
  players: PlayerBoard[]
}

